INSERT INTO unit_variant_characteristic (unit_variant_id, characteristic_type_id, characteristic_json) SELECT uv.unit_variant_id, ct.characteristic_type_id, '{"source":{"catalogue":"Galactic Republic.cat","revision":"14","profile":"Delta-7 Aethersprite Squadron","characteristic":"Speed"},"raw_value":"4","value":4}'::jsonb FROM unit_variant uv JOIN unit_type ut ON ut.unit_type_id = uv.unit_type_id JOIN unit_classification uc ON uc.unit_classification_id = ut.unit_classification_id JOIN faction f ON f.faction_id = uc.faction_id JOIN characteristic_type ct ON ct.characteristic_type_name = 'Speed' WHERE f.faction_name = 'Galactic Republic' AND uc.unit_classification_name = 'Squadron' AND ut.unit_type_name = 'Delta-7 Aethersprite' AND uv.unit_variant_name = 'Delta-7 Aethersprite Squadron';
