INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.galactic republic.e679-4ba7-6c1e-0a4a.b05e-7612-9738-5dcb', 'Plo Koon', 'Imported from Galactic Republic.cat profile 2.0 Commander.', 'Plo Koon', '{"characteristics":{"Commander Ability":{"raw_value":"While a friendly squadron is attacking a ship that is at distance 1-3 of a friendly ship, the attacker may add 1 blue die set to an [Accuracy] icon to its attack pool. That die cannon be rerolled or changed. Friendly squadrons without Adept gain Grit while they are at distance 1 of a friendly squadron with Adept.","value":"While a friendly squadron is attacking a ship that is at distance 1-3 of a friendly ship, the attacker may add 1 blue die set to an [Accuracy] icon to its attack pool. That die cannon be rerolled or changed. Friendly squadrons without Adept gain Grit while they are at distance 1 of a friendly squadron with Adept."},"Setup":{"raw_value":"","value":""},"Recur":{"raw_value":"","value":""},"Ready Cost":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"26.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"2.0 Commander","catalogue_entry_name":"Plo Koon"}'::jsonb, '{"file":"Galactic Republic.cat","revision":"14","entry_id":"e679-4ba7-6c1e-0a4a","profile_id":"b05e-7612-9738-5dcb"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.commander' WHERE g.game_name = 'Star Wars: Armada';
