INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.rebel fleet.c8aa-725d-8c28-bf35.6c5e-1bf5-93c7-b3a0', 'Admiral Raddus', 'Imported from Rebel Fleet.cat profile 2.0 Commander.', 'Admiral Raddus', '{"characteristics":{"Commander Ability":{"raw_value":"Before deploying fleets, you may set aside 1 other friendly ship with a command value of 3 or less. At the start of any round, you may deploy that ship at distance 1-2 of you. That ship cannot be deployed overlapping squadrons and cannot be the first ship to activate that round.","value":"Before deploying fleets, you may set aside 1 other friendly ship with a command value of 3 or less. At the start of any round, you may deploy that ship at distance 1-2 of you. That ship cannot be deployed overlapping squadrons and cannot be the first ship to activate that round."},"Setup":{"raw_value":"","value":""},"Recur":{"raw_value":"","value":""},"Ready Cost":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"26.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"2.0 Commander","catalogue_entry_name":"Admiral Raddus"}'::jsonb, '{"file":"Rebel Fleet.cat","revision":"55","entry_id":"c8aa-725d-8c28-bf35","profile_id":"6c5e-1bf5-93c7-b3a0"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.commander' WHERE g.game_name = 'Star Wars: Armada';
