INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.rebel fleet.61ad-cbfd-3c0a-3671.7dfa-9d4b-51af-c771', 'Boarding Engineers', 'Imported from Rebel Fleet.cat profile 7.1 Dual Type Upgrade - Weapons Team & Offensive Retrofit.', 'Boarding Engineers', '{"characteristics":{"Dual Type Upgrade Ability":{"raw_value":"When you reveal a command, you may discard a [Squadron] dial or token and this card to choose 1 enemy ship at close range. Look at its facedown damage cards and flip a number of them faceup up to your engineering value (one at a time).","value":"When you reveal a command, you may discard a [Squadron] dial or token and this card to choose 1 enemy ship at close range. Look at its facedown damage cards and flip a number of them faceup up to your engineering value (one at a time)."},"Setup":{"raw_value":"","value":""},"Recur":{"raw_value":"","value":""},"Ready Cost":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"2.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"}],"profile_type":"7.1 Dual Type Upgrade - Weapons Team \u0026 Offensive Retrofit","catalogue_entry_name":"Boarding Engineers"}'::jsonb, '{"file":"Rebel Fleet.cat","revision":"55","entry_id":"61ad-cbfd-3c0a-3671","profile_id":"7dfa-9d4b-51af-c771"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.dual_upgrade' WHERE g.game_name = 'Star Wars: Armada';
