INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.separatist alliance.9792-ef9e-f9f1-8bfc.c8f8-ab41-93b9-adcb', 'Hyperwave Signal Boost', 'Imported from Separatist Alliance.cat profile 5.1 Offensive Retrofit.', 'Hyperwave Signal Boost', '{"characteristics":{"Offensive Retrofit Ability":{"raw_value":"During the Squadron Phase, when it is your fleet\u0027s turn to activate squadrons, you may exhaust this card to choose a number of unactivated, friendly squadrons at close-long range up to your squadron value. This turn, activate each of those squadrons. While attacking, each of those squadrons with AI are treated as if activated by a [Squadron] command.","value":"During the Squadron Phase, when it is your fleet\u0027s turn to activate squadrons, you may exhaust this card to choose a number of unactivated, friendly squadrons at close-long range up to your squadron value. This turn, activate each of those squadrons. While attacking, each of those squadrons with AI are treated as if activated by a [Squadron] command."},"Setup":{"raw_value":"","value":""},"Recur":{"raw_value":"Non-Recur","value":"Non-Recur"},"Ready Cost":{"raw_value":"1 [Repair] or [Squadron] token","value":"1 [Repair] or [Squadron] token"}},"costs":[{"name":"pts","value":"3.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"}],"profile_type":"5.1 Offensive Retrofit","catalogue_entry_name":"Hyperwave Signal Boost"}'::jsonb, '{"file":"Separatist Alliance.cat","revision":"13","entry_id":"9792-ef9e-f9f1-8bfc","profile_id":"c8f8-ab41-93b9-adcb"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.offensive_retrofit' WHERE g.game_name = 'Star Wars: Armada';
