INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.separatist alliance.513a-adef-a6ba-24d6.893a-cadb-b1ee-81df', 'Jedi Hostage', 'Imported from Separatist Alliance.cat profile 4.2 Fleet Command.', 'Jedi Hostage', '{"characteristics":{"Fleet Command Ability":{"raw_value":"When an enemy ship declares you as the target of a non-[Salvo] attack, if this card is readied, the attacker gains a raid token of its choice, if able. When an enemy ship at close range reveals a command, it may discard a [Squadron] dial to exhaust this card. While defending, if this card is exhausted, you cannot spend more than 1 defense token.","value":"When an enemy ship declares you as the target of a non-[Salvo] attack, if this card is readied, the attacker gains a raid token of its choice, if able. When an enemy ship at close range reveals a command, it may discard a [Squadron] dial to exhaust this card. While defending, if this card is exhausted, you cannot spend more than 1 defense token."},"Setup":{"raw_value":"","value":""},"Recur":{"raw_value":"Non-Recur","value":"Non-Recur"},"Ready Cost":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"3.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"4.2 Fleet Command","catalogue_entry_name":"Jedi Hostage"}'::jsonb, '{"file":"Separatist Alliance.cat","revision":"13","entry_id":"513a-adef-a6ba-24d6","profile_id":"893a-cadb-b1ee-81df"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.fleet_command' WHERE g.game_name = 'Star Wars: Armada';
