INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.separatist alliance.7501-1e27-8d82-0760.f26c-e120-fe2d-da0d', 'Gilded Aegis', 'Imported from Separatist Alliance.cat profile 2.1 Title.', 'Gilded Aegis', '{"characteristics":{"Title Ability":{"raw_value":"At the end of the Command Phase or Ship Phase, you may discard a [Redirect] defense token to move shields to 1 of your hull zones. If you do, the number of shields in that zone cannot exceed a maximum of \"6\". You cannot recover shields in that zone while it is greater than its maximum shield value.","value":"At the end of the Command Phase or Ship Phase, you may discard a [Redirect] defense token to move shields to 1 of your hull zones. If you do, the number of shields in that zone cannot exceed a maximum of \"6\". You cannot recover shields in that zone while it is greater than its maximum shield value."},"Setup":{"raw_value":"","value":""},"Recur":{"raw_value":"","value":""},"Ready Cost":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"5.0"}],"constraints":[{"field":"selections","scope":"roster","value":"1.0","type":"max"},{"field":"selections","scope":"parent","value":"1.0","type":"max"}],"profile_type":"2.1 Title","catalogue_entry_name":"Gilded Aegis"}'::jsonb, '{"file":"Separatist Alliance.cat","revision":"13","entry_id":"7501-1e27-8d82-0760","profile_id":"f26c-e120-fe2d-da0d"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.title' WHERE g.game_name = 'Star Wars: Armada';
