INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.separatist alliance.da49-8d6f-866e-397a.610a-52ee-64a7-a7b3', 'Nova Defiant', 'Imported from Separatist Alliance.cat profile 2.1 Title.', 'Nova Defiant', '{"characteristics":{"Title Ability":{"raw_value":"When you are deployed, you must choose 1 of each type of command token for this card. Your command value is increased to 4. You can be assigned more than 1 of each type of command token. When you reveal a command, you may discard all of the tokens from this card to gain them.","value":"When you are deployed, you must choose 1 of each type of command token for this card. Your command value is increased to 4. You can be assigned more than 1 of each type of command token. When you reveal a command, you may discard all of the tokens from this card to gain them."},"Setup":{"raw_value":"1 of each command token","value":"1 of each command token"},"Recur":{"raw_value":"","value":""},"Ready Cost":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"4.0"}],"constraints":[{"field":"selections","scope":"roster","value":"1.0","type":"max"},{"field":"selections","scope":"parent","value":"1.0","type":"max"}],"profile_type":"2.1 Title","catalogue_entry_name":"Nova Defiant"}'::jsonb, '{"file":"Separatist Alliance.cat","revision":"13","entry_id":"da49-8d6f-866e-397a","profile_id":"610a-52ee-64a7-a7b3"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.title' WHERE g.game_name = 'Star Wars: Armada';
