INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.separatist alliance.0647-8947-2987-a205.61ec-7ede-4b3e-1b63', 'Patriot Fist', 'Imported from Separatist Alliance.cat profile 2.1 Title.', 'Patriot Fist', '{"characteristics":{"Title Ability":{"raw_value":"While attacking a ship at medium-long range, if this is your first attack during your activation, you may add 2 blue dice to your attack pool. If you do, you cannot attack again during this activation.","value":"While attacking a ship at medium-long range, if this is your first attack during your activation, you may add 2 blue dice to your attack pool. If you do, you cannot attack again during this activation."},"Setup":{"raw_value":"","value":""},"Recur":{"raw_value":"","value":""},"Ready Cost":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"6.0"}],"constraints":[{"field":"selections","scope":"roster","value":"1.0","type":"max"},{"field":"selections","scope":"parent","value":"1.0","type":"max"}],"profile_type":"2.1 Title","catalogue_entry_name":"Patriot Fist"}'::jsonb, '{"file":"Separatist Alliance.cat","revision":"13","entry_id":"0647-8947-2987-a205","profile_id":"61ec-7ede-4b3e-1b63"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.title' WHERE g.game_name = 'Star Wars: Armada';
