INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.separatist alliance.9d22-f3eb-9ea9-79e0.874a-c69f-3b70-4098', 'Invisible Hand', 'Imported from Separatist Alliance.cat profile 2.1 Title.', 'Invisible Hand', '{"characteristics":{"Title Ability":{"raw_value":"While deploying fleets, if you are in the play area, when you would deploy a squadron with Swarm, you may set that squadron aside next to your ship card instead. You may set aside up to 5 squadrons in this way. [Squadron]: Choose any number of squadrons set aside with this card. Then place them within distance 1 - 3 of you. During your activation, those squadrons cannot move and, if they have AI, may increase their AI value by 1.","value":"While deploying fleets, if you are in the play area, when you would deploy a squadron with Swarm, you may set that squadron aside next to your ship card instead. You may set aside up to 5 squadrons in this way. [Squadron]: Choose any number of squadrons set aside with this card. Then place them within distance 1 - 3 of you. During your activation, those squadrons cannot move and, if they have AI, may increase their AI value by 1."},"Setup":{"raw_value":"","value":""},"Recur":{"raw_value":"","value":""},"Ready Cost":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"8.0"}],"constraints":[{"field":"selections","scope":"roster","value":"1.0","type":"max"},{"field":"selections","scope":"parent","value":"1.0","type":"max"}],"profile_type":"2.1 Title","catalogue_entry_name":"Invisible Hand"}'::jsonb, '{"file":"Separatist Alliance.cat","revision":"13","entry_id":"9d22-f3eb-9ea9-79e0","profile_id":"874a-c69f-3b70-4098"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.title' WHERE g.game_name = 'Star Wars: Armada';
