INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.separatist alliance.18d8-c65f-cd4a-0423.06e8-7a84-962e-e12a', 'Lucid Voice', 'Imported from Separatist Alliance.cat profile 2.1 Title.', 'Lucid Voice', '{"characteristics":{"Title Ability":{"raw_value":"Treat your rear hull zone\u0027s printed battery armament as 3 red dice. The battery armament of your left and right hull zones are each increased by 1 black die and decreased by 1 blue die.","value":"Treat your rear hull zone\u0027s printed battery armament as 3 red dice. The battery armament of your left and right hull zones are each increased by 1 black die and decreased by 1 blue die."},"Setup":{"raw_value":"","value":""},"Recur":{"raw_value":"","value":""},"Ready Cost":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"6.0"}],"constraints":[{"field":"selections","scope":"roster","value":"1.0","type":"max"},{"field":"selections","scope":"parent","value":"1.0","type":"max"}],"profile_type":"2.1 Title","catalogue_entry_name":"Lucid Voice"}'::jsonb, '{"file":"Separatist Alliance.cat","revision":"13","entry_id":"18d8-c65f-cd4a-0423","profile_id":"06e8-7a84-962e-e12a"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.title' WHERE g.game_name = 'Star Wars: Armada';
