INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.d927-a1fa-181c-569f.747e-a85b-367f-e583', 'Dangerous Territory', 'Imported from Star_Wars_Armada.gst profile 8.3 Navigation Objective.', 'Dangerous Territory', '{"characteristics":{"Setup":{"raw_value":"Obstacles must be placed in the setup area beyond distance 5 of both players\u0027 edges. After placing obstacles, place 1 objective token on each obstacle.","value":"Obstacles must be placed in the setup area beyond distance 5 of both players\u0027 edges. After placing obstacles, place 1 objective token on each obstacle."},"Special Rule":{"raw_value":"When a ship overlaps an obstacle, the ship\u0027s owner may remove the objective token on that obstacle to gain 1 victory token. When one of the second player\u0027s ships overlaps an asteroid field or debris field, that obstacle has no effect.","value":"When a ship overlaps an obstacle, the ship\u0027s owner may remove the objective token on that obstacle to gain 1 victory token. When one of the second player\u0027s ships overlaps an asteroid field or debris field, that obstacle has no effect."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"15","value":"15"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.3 Navigation Objective","catalogue_entry_name":"Dangerous Territory"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"d927-a1fa-181c-569f","profile_id":"747e-a85b-367f-e583"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_navigation' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.9479-83d8-20a5-74d4.52a3-0065-a46e-9c4f', 'Intel Sweep', 'Imported from Star_Wars_Armada.gst profile 8.3 Navigation Objective.', 'Intel Sweep', '{"characteristics":{"Setup":{"raw_value":"After placing obstacles, the players alternate placing a total of 5 objective tokens in the setup area, starting with the second player. Each token must be placed in the play area beyond distance 5 of both players\u0027 edges and beyond distance 3 of all other objective tokens. Then each player chooses one of his ships to be an objective ship, starting with the first player.","value":"After placing obstacles, the players alternate placing a total of 5 objective tokens in the setup area, starting with the second player. Each token must be placed in the play area beyond distance 5 of both players\u0027 edges and beyond distance 3 of all other objective tokens. Then each player chooses one of his ships to be an objective ship, starting with the first player."},"Special Rule":{"raw_value":"When a player\u0027s objective ship reveals a command dial, that player may choose 1 objective token at distance 1 of that ship and remove it from the play area to gain 1 victory token.","value":"When a player\u0027s objective ship reveals a command dial, that player may choose 1 objective token at distance 1 of that ship and remove it from the play area to gain 1 victory token."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"If a player has more victory tokens than his opponent, increase his final score by 75.","value":"If a player has more victory tokens than his opponent, increase his final score by 75."},"Victory Token Value":{"raw_value":"--","value":"--"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.3 Navigation Objective","catalogue_entry_name":"Intel Sweep"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"9479-83d8-20a5-74d4","profile_id":"52a3-0065-a46e-9c4f"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_navigation' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.b3d8-5ed2-b8a4-5e85.653b-7b07-96be-d0f5', 'Minefields', 'Imported from Star_Wars_Armada.gst profile 8.3 Navigation Objective.', 'Minefields', '{"characteristics":{"Setup":{"raw_value":"The second player places all obstacles. He can place them anywhere in the setup area (even in deployment zones) and must place them beyond distance 5 of each other. Then he places 6 objective tokens. Each objective token must be placed at distance 1 of an obstacle and beyond distance 1 of all other objective tokens.","value":"The second player places all obstacles. He can place them anywhere in the setup area (even in deployment zones) and must place them beyond distance 5 of each other. Then he places 6 objective tokens. Each objective token must be placed at distance 1 of an obstacle and beyond distance 1 of all other objective tokens."},"Special Rule":{"raw_value":"If a ship ends its movement at distance 1 of an objective token, remove that objective token from the play area and roll 2 blue dice. That ship is dealt 1 facedown damage card for each Hit or Critical icon rolled. If there is at least 1 Critical icon, deal the first damage card faceup.","value":"If a ship ends its movement at distance 1 of an objective token, remove that objective token from the play area and roll 2 blue dice. That ship is dealt 1 facedown damage card for each Hit or Critical icon rolled. If there is at least 1 Critical icon, deal the first damage card faceup."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"--","value":"--"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.3 Navigation Objective","catalogue_entry_name":"Minefields"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"b3d8-5ed2-b8a4-5e85","profile_id":"653b-7b07-96be-d0f5"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_navigation' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.b595-a1e1-d5d8-6f98.9ca1-06ca-2f0b-6de0', 'Superior Positions', 'Imported from Star_Wars_Armada.gst profile 8.3 Navigation Objective.', 'Superior Positions', '{"characteristics":{"Setup":{"raw_value":"The first player must deploy all of his ships and squadrons before the second player.","value":"The first player must deploy all of his ships and squadrons before the second player."},"Special Rule":{"raw_value":"After a ship or squadron performs an attack against the rear hull zone of another ship, if the defender suffered at least 1 damage, the attacker\u0027s owner gains 1 victory token.","value":"After a ship or squadron performs an attack against the rear hull zone of another ship, if the defender suffered at least 1 damage, the attacker\u0027s owner gains 1 victory token."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"15","value":"15"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.3 Navigation Objective","catalogue_entry_name":"Superior Positions"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"b595-a1e1-d5d8-6f98","profile_id":"9ca1-06ca-2f0b-6de0"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_navigation' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.d15d-5599-3518-c84d.10f5-6a61-fa7c-cec0', 'Navigational Hazards', 'Imported from Star_Wars_Armada.gst profile 8.3 Navigation Objective.', 'Navigational Hazards', '{"characteristics":{"Setup":{"raw_value":"Place obstacles as normal, excluding the station. Then, the second player places the station in the setup area beyond distance 1 of all obstacles and beyond distance 5 of both players\u0027 edges.","value":"Place obstacles as normal, excluding the station. Then, the second player places the station in the setup area beyond distance 1 of all obstacles and beyond distance 5 of both players\u0027 edges."},"Special Rule":{"raw_value":"When a ship overlaps an obstacle and suffers 1 or more damage or is dealt 1 or more damage cards, the opposing fleet\u0027s owner gains 1 victory token.","value":"When a ship overlaps an obstacle and suffers 1 or more damage or is dealt 1 or more damage cards, the opposing fleet\u0027s owner gains 1 victory token."},"End of Round":{"raw_value":"Starting with the second player and alternating, each player chooses 1 asteroid or debris field that does not have an objective token on it, and moves it to within distance 1-2 of its current location. Then, he places an objective token on that obstacle. An obstacle cannot be moved so that it overlaps a ship, squadron, or other obstacle. At the start of the next round, remove all objective tokens from the play area.","value":"Starting with the second player and alternating, each player chooses 1 asteroid or debris field that does not have an objective token on it, and moves it to within distance 1-2 of its current location. Then, he places an objective token on that obstacle. An obstacle cannot be moved so that it overlaps a ship, squadron, or other obstacle. At the start of the next round, remove all objective tokens from the play area."},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"15","value":"15"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.3 Navigation Objective","catalogue_entry_name":"Navigational Hazards"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"d15d-5599-3518-c84d","profile_id":"10f5-6a61-fa7c-cec0"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_navigation' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.f2b6-8c61-99f4-2c5f.8b43-e2c4-e071-a312', 'Salvage Run', 'Imported from Star_Wars_Armada.gst profile 8.3 Navigation Objective.', 'Salvage Run', '{"characteristics":{"Setup":{"raw_value":"The second player places the station in the center of the play area. Then, starting with the second player, the players alternate placing the remaining obstacles, adding the 2 dust field obstacles, at distance 1-5 of the station. After placing obstacles, the second player places a total of 4 objective tokens in the setup area. Each token must be at distance 1 of the station and beyond distance 1 of all other objective tokens. After deploying fleets, each of the second player\u0027s ships gains a Navigation token.","value":"The second player places the station in the center of the play area. Then, starting with the second player, the players alternate placing the remaining obstacles, adding the 2 dust field obstacles, at distance 1-5 of the station. After placing obstacles, the second player places a total of 4 objective tokens in the setup area. Each token must be at distance 1 of the station and beyond distance 1 of all other objective tokens. After deploying fleets, each of the second player\u0027s ships gains a Navigation token."},"Special Rule":{"raw_value":"When a player\u0027s ship reveals a command dial, that player may chooose 1 objective token at distance 1 of that ship and remove it from the play area to gain 1 victory token.","value":"When a player\u0027s ship reveals a command dial, that player may chooose 1 objective token at distance 1 of that ship and remove it from the play area to gain 1 victory token."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"20","value":"20"}},"cos