INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.77fe-7d9b-7709-2ecc.ef06-bd10-5ba6-bc06', 'Sensor Net', 'Imported from Star_Wars_Armada.gst profile 8.3 Navigation Objective.', 'Sensor Net', '{"characteristics":{"Setup":{"raw_value":"After placing obstacles, the players alternate placing a total of 4 objective tokens in the setup area, starting with the first player. Each token must be placed in the setup area beyond distance 5 of both players\u0027 edges and beyond distance 3 of all other objective tokens.","value":"After placing obstacles, the players alternate placing a total of 4 objective tokens in the setup area, starting with the first player. Each token must be placed in the setup area beyond distance 5 of both players\u0027 edges and beyond distance 3 of all other objective tokens."},"Special Rule":{"raw_value":"When a ship reveals a command dial, if it at distance 1 of at least 1 objective token, its owner gains 1 victory token. Then its owner chooses 1 of those objective tokens. The opposing player must move that token. If he is the first player, he moves the token so it is at distance 1-2 of its current location. If he is the second player, he moves it so it is at distance 1-4 of its current location.","value":"When a ship reveals a command dial, if it at distance 1 of at least 1 objective token, its owner gains 1 victory token. Then its owner chooses 1 of those objective tokens. The opposing player must move that token. If he is the first player, he moves the token so it is at distance 1-2 of its current location. If he is the second player, he moves it so it is at distance 1-4 of its current location."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"15","value":"15"}},"costs":[{"name":"pts","value":"0.0"}],"