INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.030f-14e6-940a-1b3f.40f8-6529-82cb-66ce', 'Solar Corona', 'Imported from Star_Wars_Armada.gst profile 8.3 Navigation Objective.', 'Solar Corona', '{"characteristics":{"Setup":{"raw_value":"The first player must deploy all of his ships and squadrons before the second player. After the second player deploys ships and squadrons, the second player must choose 1 of the 3\u0027 edges of the play area to be the Corona.","value":"The first player must deploy all of his ships and squadrons before the second player. After the second player deploys ships and squadrons, the second player must choose 1 of the 3\u0027 edges of the play area to be the Corona."},"Special Rule":{"raw_value":"While a ship is attacking, before resolving any attack effects, if any portion of the corona is inside the attacking hull zone\u0027s firing arc, the attacker must discard 1 die with an Accuracy icon from the attack pool, if applicable.","value":"While a ship is attacking, before resolving any attack effects, if any portion of the corona is inside the attacking hull zone\u0027s firing arc, the attacker must discard 1 die with an Accuracy icon from the attack pool, if applicable."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"--","value":"--"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.3 Navigation Objective","catalogue_entry_name":"Solar Corona"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"030f-14e6-940a-1b3f","profile_id":"40f8-6529-82cb-66ce"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_