INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.5228-6303-32f5-4d15.d0ad-0353-2727-964b', 'Doomed Station', 'Imported from Star_Wars_Armada.gst profile 8.3 Navigation Objective.', 'Doomed Station', '{"characteristics":{"Setup":{"raw_value":"The second player places the gravity rift in the center of the setup area. Then, starting with the first player, the players alternate placing the remaining obstacles, excluding the station. Then the second player places the station in the setup area beyond distance 1 of all obstacles and beyond distance 5 of both player\u0027s edges.","value":"The second player places the gravity rift in the center of the setup area. Then, starting with the first player, the players alternate placing the remaining obstacles, excluding the station. Then the second player places the station in the setup area beyond distance 1 of all obstacles and beyond distance 5 of both player\u0027s edges."},"Special Rule":{"raw_value":"","value":""},"End of Round":{"raw_value":"Starting with the second player and alternating, each player chooses 1 obstacle that does not have an objective token on it and moves it to within distance 1-2 of its current location toward the gravity rift (which cannot be chosen). Then that player places an objective token on that obstacle. When an obstacle touches the gravity rift, that obstacle is removed from the play area. After all obstacles are moved, each player sums the command values of their ships at distance 1 of the station. The player with the highest total gains 1 victory token. Then remove all objectives tokens from the play area.","value":"Starting with the second player and alternating, each player chooses 1 obstacle that does not have an objective token on it and moves it to within distance 1-2 of its current location toward the gravity rift (which cannot be chosen). Then that player places an objective token on that obstacle. When an obstacle touches the gravity rift, that obstacle is removed from the play area. After all obstacles are moved, each player sums the command values of their ships at distance 1 of the station. The player with the highest total gains 1 victory token. Then remove all objectives tokens from the play area."},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"20","value":"20"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.3 Navigation Objective","catalogue_entry_name":"Doomed Station"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"5228-6303-32f5-4d15","profile_id":"d0ad-0353-2727-964b"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_navigation' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.013d-2b2d-0325-70fd.2284-70b6-dc33-af13', 'Hyperspace Migration', 'Imported from Star_Wars_Armada.gst profile 8.3 Navigation Objective.', 'Hyperspace Migration', '{"characteristics":{"Setup":{"raw_value":"Place obstacles as normal, excluding the station. Then the second player places 1 objective token in the play area at distance 1 of a 3\u0027 edge and another objective token at distance 1 of the opposite 3\u0027 edge.","value":"Place obstacles as normal, excluding the station. Then the second player places 1 objective token in the play area at distance 1 of a 3\u0027 edge and another objective token at distance 1 of the opposite 3\u0027 edge."},"Special Rule":{"raw_value":"At the start of the Ship Phase of the first and third rounds, the second player places 1 purrgil not in the play area at distance 1 of 1 objective token (the objective token must be the same during both rounds). When a purrgil moves, it must move toward the objective token at the opposite 3\u0027 edge. When a purrgil touches that objective token, that purrgil is removed from the play area.","value":"At the start of the Ship Phase of the first and third rounds, the second player places 1 purrgil not in the play area at distance 1 of 1 objective token (the objective token must be the same during both rounds). When a purrgil moves, it must move toward the objective token at the opposite 3\u0027 edge. When a purrgil touches that objective token, that purrgil is removed from the play area."},"End of Round":{"raw_value":"If a ship has 1 objective token on it, remove the token and that ship\u0027s owner gains 1 victory token. If a ship is at distance 1 from a purrgil and has no objective tokens on it, place 1 objective token on the ship.","value":"If a ship has 1 objective token on 