INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.51cf-53ee-0118-5cd7.273c-9474-6c0a-e6a6', 'Advanced Gunnery', 'Imported from Star_Wars_Armada.gst profile 8.1 Assault Objective.', 'Advanced Gunnery', '{"characteristics":{"Setup":{"raw_value":"After deploying fleets, each player chooses 1 of his ships to be an objective ship, starting with the first player.","value":"After deploying fleets, each player chooses 1 of his ships to be an objective ship, starting with the first player."},"Special Rule":{"raw_value":"The first player\u0027s objective ship may perform each of its attacks from the same hull zone. It cannot target the same hull zone or squadron more than once each round with that hull zone. The second player\u0027s objective ship may perform each of its attacks from the same hull zone, and it may do so against the same targets.","value":"The first player\u0027s objective ship may perform each of its attacks from the same hull zone. It cannot target the same hull zone or squadron more than once each round with that hull zone. The second player\u0027s objective ship may perform each of its attacks from the same hull zone, and it may do so against the same targets."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"The fleet point cost of a destroyed objective ship is doubled. Do not double the cost of its upgrade cards.","value":"The fleet point cost of a destroyed objective ship is doubled. Do not double the cost of its upgrade cards."},"Victory Token Value":{"raw_value":"--","value":"--"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.1 Assault Objective","catalogue_entry_name":"Advanced Gunnery"}'::jsonb, '