INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.5917-9e03-b1cd-a425.7320-787d-d21b-69b7', 'Precision Strike', 'Imported from Star_Wars_Armada.gst profile 8.1 Assault Objective.', 'Precision Strike', '{"characteristics":{"Setup":{"raw_value":"After deploying fleets, each of the second player\u0027s ships gains a Concentrate Fire token.","value":"After deploying fleets, each of the second player\u0027s ships gains a Concentrate Fire token."},"Special Rule":{"raw_value":"When a squadron with Bomber or a ship is attacking, it may spend 1 die with a Hit icon to flip 1 random facedown damage card on the defender faceup. After a squadron with Bomber or a ship performs an attack, its owner gains 1 victory token for each damage card that was dealt faceup or flipped faceup during that attack.","value":"When a squadron with Bomber or a ship is attacking, it may spend 1 die with a Hit icon to flip 1 random facedown damage card on the defender faceup. After a squadron with Bomber or a ship performs an attack, its owner gains 1 victory token for each damage card that was dealt faceup or flipped faceup during that attack."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"15","value":"15"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.1 Assault Objective","catalogue_entry_name":"Precision Strike"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"5917-9e03-b1cd-a425","profile_id":"7320-787d-d21b-69b7"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_assault' WHERE g.game_name = 'Star Wars: Arm