INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.39e0-3111-50ea-6191.a1b1-cf62-3007-a767', 'Blockade Run', 'Imported from Star_Wars_Armada.gst profile 8.1 Assault Objective.', 'Blockade Run', '{"characteristics":{"Setup":{"raw_value":"The 3\u0027 edges of the play area become the player edges. Each player\u0027s deployment zone is within 2 range ruler lengths of his edge. The second player places all obstacles. Obstacles must be placed in the play area beyond 2 range ruler lengths of both player edges, and beyond distance 1 of other obstacles.","value":"The 3\u0027 edges of the play area become the player edges. Each player\u0027s deployment zone is within 2 range ruler lengths of his edge. The second player places all obstacles. Obstacles must be placed in the play area beyond 2 range ruler lengths of both player edges, and beyond distance 1 of other obstacles."},"Special Rule":{"raw_value":"The second player assigns 1 objective token to each of his ships. When a ship with an objective token is destroyed, the first player gains 1 victory token.","value":"The second player assigns 1 objective token to each of his ships. When a ship with an objective token is destroyed, the first player gains 1 victory token."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"The second player gains 1 victory token for each ship with an objective token within the first player\u0027s deployment zone.","value":"The second player gains 1 victory token for each ship with an objective token within the first player\u0027s deployment zone."},"Victory Token Value":{"raw_value":"20","value":"20"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.1 Assault Objective","catalogue_entry_name":"Blockade Run"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"39e0-3111-50ea-6191","profile_id":"a1b1-cf62-3007-a767"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_assault' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.2f07-d707-4e37-b69d.a323-dbbf-8659-43e0', 'Close-Range Intel Scan', 'Imported from Star_Wars_Armada.gst profile 8.1 Assault Objective.', 'Close-Range Intel Scan', '{"characteristics":{"Setup":{"raw_value":"Place obstacles, adding the 2 dust fields, as normal.","value":"Place obstacles, adding the 2 dust fields, as normal."},"Special Rule":{"raw_value":"While one of the second player\u0027s ships is attacking a ship, the attacker may spend 1 die with an Accuracy icon. If it does, the attacker\u0027s owner gains 1 victory token. While one of the first player\u0027s ships is attacking a ship, the attacker may spend 2 dice with Accuracy icons. If it does, the attacker\u0027s owner gains 1 victory token.","value":"While one of the second player\u0027s ships is attacking a ship, the attacker may spend 1 die with an Accuracy icon. If it does, the attacker\u0027s owner gains 1 victory token. While one of the first player\u0027s ships is attacking a ship, the attacker may spend 2 dice with Accuracy icons. If it does, the attacker\u0027s owner gains 1 victory token."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"10","value":"10"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.1 Assault Objective","catalogue_entry_name":"Close-Range Intel Scan"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"2f07-d707-4e37-b69d","profile_id":"a323-dbbf-8659-43e0"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_assault' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.9e4c-b6bb-85a7-dc3b.8614-d7e1-66b8-0bf7', 'Targeting Beacons', 'Imported from Star_Wars_Armada.gst profile 8.1 Assault Objective.', 'Targeting Beacons', '{"characteristics":{"Setup":{"raw_value":"After placing obstacles, the players alternate placing a total of 4 objective tokens in the setup area, starting with the second player.","value":"After placing obstacles, the players alternate placing a total of 4 objective tokens in the setup area, starting with the second player."},"Special Rule":{"raw_value":"While one of the second player\u0027s ships is attacking a ship that is at distance 1-2 of an objective token, the attacker may reroll up to 2 attack dice in the attack pool.","value":"While one of the second player\u0027s ships is attacking a ship that is at distance 1-2 of an objective token, the attacker may reroll up to 2 attack dice in the attack pool."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"--","value":"--"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.1 Assault Objective","catalogue_entry_name":"Targeting Beacons"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"9e4c-b6bb-85a7-dc3b","profile_id":"8614-d7e1-66b8-0bf7"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_assault' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.84dc-dcf7-acd7-e6a6.7a15-5c15-62da-01a5', 'Station Assault', 'Imported from Star_Wars_Armada.gst profile 8.1 Assault Objective.', 'Station Assault', '{"characteristics":{"Setup":{"raw_value":"Place obstacles as normal, excluding the station. Then, the second player places 2 stations in the setup area. Each station must be placed beyond distance 1 of all obstacles and beyond distance 3 of both players\u0027 edges. Both stations are unarmed stations; place both Unarmed Station cards near the second player\u0027s ship cards.","value":"Place obstacles as normal, excluding the station. Then, the second player places 2 stations in the setup area. Each station must be placed beyond distance 1 of all obstacles and beyond distance 3 of both players\u0027 edges. Both stations are unarmed stations; place both Unarmed Station cards near the second player\u0027s ship cards."},"Special Rule":{"raw_value":"The first player\u0027s ships and squadrons cannot resolve an unarmed station\u0027s effect to discard damage cards or recover hull points when they overlap it.","value":"The first player\u0027s ships and squadrons cannot resolve an unarmed station\u0027s effect to discard damage cards or recover hull points when they overlap it."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"The second player gains 1 victory token for each unarmed station that is not destroyed. The first player gains 1 victory token for each unarmed station that is destroyed.","value":"The second player gains 1 victory token for each unarmed station that is not destroyed. The first player gains 1 victory token for each unarmed station that is destroyed."},"Victory Token Value":{"raw_value":"40","value":"40"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.1 Assault Objective","catalogue_entry_name":"Station Assault"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"84dc-dcf7-acd7-e6a6","profile_id":"7a15-5c15-62da-01a5"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_assault' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.1d1b-754d-8095-db28.bd9f-85e0-429b-f77a', 'Ion Storm', 'Imported from Star_Wars_Armada.gst profile 8.1 Assault Objective.', 'Ion Storm', '{"characteristics":{"Setup":{"raw_value":"The second player places all obstacles, excluding the station, beyond distance 5 of both players\u0027 edges.","value":"The second player places all obstacles, excluding the station, beyond distance 5 of both players\u0027 edges."},"Special Rule":{"raw_value":"When a ship that does not have an objective token ends it movement beyond distance 2 of any obstacles (or beyond distance 1 if that ship belongs to the first player), assign 1 objective token to that ship. When a ship resolved a [Engineering] command, it may discard its objective token. Each ship has the following critical effect: [Crit]: If the defender has an objective toke, the attacking ship\u0027s owner gains 1 victory token. Then choose and discard 1 command token from the defender. If the defender does not have any command tokens, the defending hull zone loses 1 shield instead.","value":"When a ship that does not have an objective token ends it movement beyond distance 2 of any obstacles (or beyond distance 1 if that ship belongs to the first player), assign 1 objective token to that ship. When a ship resolved a [Engineering] command, it may discard its objective token. Each ship has the following critical effect: [Crit]: If the defender has an objective toke, the attacking ship\u0027s owner gains 1 victory token. Then choose and discard 1 command token from the defender. If the defender does not have any command tokens, the defending hull zone loses 1 shield instead."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"15","value":"15"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.1 Assault Objective","catalogue_entry_name":"Ion Storm"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"1d1b-754d-8095-db28","profile_id":"bd9f-85e0-429b-f77a"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_assault' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.f804-d8ee-5ba3-a1af.cd09-0235-4dff-a429', 'Marked for Destruction', 'Imported from Star_Wars_Armada.gst profile 8.1 Assault Objective.', 'Marked for Destruction', '{"characteristics":{"Setup":{"raw_value":"Place obstacles as normal, adding the 2 dust fields and excluding the station and asteroid fields. Then the second player places the 2 purrgil in the setup area. Each purrgil must be placed beyond distance 1 of all obstacles and beyond distance 5 of both player\u0027s edges.","value":"Place obstacles as normal, adding the 2 dust fields and excluding the station and asteroid fields. Then the second player places the 2 purrgil in the setup area. Each purrgil must be placed beyond distance 1 of all obstacles and beyond distance 5 of both player\u0027s edges."},"Special Rule":{"raw_value":"Each ship has the following critical effect: [Crit]: If this attack is at close-medium range, remove all objective tokens from enemy ships. Then assign an objective token to the defender. After a player moves a purrgil, if that purrgil is at distance 1 of a ship with an objective token, that player may choose and discard 1 objective token. Then that ship suffers 1 facedown damage and the oppsoing fleet\u0027s owner gains 1 victory token.","value":"Each ship has the following critical effect: [Crit]: If this attack is at close-medium range, remove all objective tokens from enemy ships. Then assign an objective token to the defender. After a player moves a purrgil, if that purrgil is at distance 1 of a ship with an objective token, that player may choose and discard 1 objective token. Then that ship suffers 1 facedown damage and the oppsoing fleet\u0027s owner gains 1 victory token."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"15","value":"15"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.1 Assault Objective","catalogue_entry_name":"Marked for Destruction"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"f804-d8ee-5ba3-a1af","profile_id":"cd09-0235-4dff-a429"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_assault' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.dd54-ca42-c658-93cd.a2d4-d297-16dd-eca8', 'Rift Assault', 'Imported from Star_Wars_Armada.gst profile 8.1 Assault Objective.', 'Rift Assault', '{"characteristics":{"Setup":{"raw_value":"Place obstacles as normal, adding the gravity rift and excluding the station.","value":"Place obstacles as normal, adding the gravity rift and excluding the station."},"Special Rule":{"raw_value":"While a ship is attacking a ship, if the defender is beyond distance 1 of any obstacles and the defender does not have an objective token, the attacker can spend 1 die with any icon to assign an objective token to the defender. While a ship with an objective token is defending, during the Resolve Attack Effects step, the attacker can discard that objective token to change 1 die to a face with a [Accuracy] icon or 1 [Hit] icon and no other icon. If the attacker belongs to the second player, it can change 1 die to a face with any icon. Then the attacker\u0027s owner gains 1 victory token.","value":"While a ship is attacking a ship, if the defender is beyond distance 1 of any obstacles and the defender does not have an objective token, the attacker can spend 1 die with any icon to assign an objective token to the defender. While a ship with an objective token is defending, during the Resolve Attack Effects step, the attacker can discard that objective token to change 1 die to a face with a [Accuracy] icon or 1 [Hit] icon and no other icon. If the attacker belongs to the second player, it can change 1 die to a face with any icon. Then the attacker\u0027s owner gains 1 victory token."},"End of Round":{"raw_value":"Each ship at distance 1-2 of the gravity rift that is at speed-1 or lower suffers 1 facedown damage card.","value":"Each ship at distance 1-2 of the gravity rift that is at speed-1 or lower suffers 1 facedown damage card."},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"10","value":"10"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.1 Assault Objective","catalogue_entry_name":"Rift Assault"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"dd54-ca42-c658-93cd","profile_id":"a2d4-d297-16dd-eca8"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_assault' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.0c64-f33a-440f-8f3f.478c-e3b9-a7bb-a792', 'Suprise Attack', 'Imported from Star_Wars_Armada.gst profile 8.1 Assault Objective.', 'Suprise Attack', '{"characteristics":{"Setup":{"raw_value":"The second player places the station at distance 1-5 of the first player\u0027s edge. Then place the remaining obstacles as normal. While deploying fleets, the first player must deploy their flagship before deploying any other ships. Their flagship must overlap the station, even if the flagship extends beyond their deployment zone. The first player cannot deploy any ship at a speed greater than half of that ship\u0027s maximum speed (rounded up.) After deploying fleets, the second player places 3 facedown command dials in a stack on this card.","value":"The second player places the station at distance 1-5 of the first player\u0027s edge. Then place the remaining obstacles as normal. While deploying fleets, the first player must deploy their flagship before deploying any other ships. Their flagship must overlap the station, even if the flagship extends beyond their deployment zone. The first player cannot deploy any ship at a speed greater than half of that ship\u0027s maximum speed (rounded up.) After deploying fleets, the second player places 3 facedown command dials in a stack on this card."},"Special Rule":{"raw_value":"At the start of the Ship Phase during the first, second, and third rounds, the second player reveals the top command dial on this card, and each of the first player\u0027s ships gain a raid token matching that dial.","value":"At the start of the Ship Phase during the first, second, and third rounds, the second player reveals the top command dial on this card, and each of the first player\u0027s ships gain a raid token matching that dial."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.1 Assault Objective","catalogue_entry_name":"Surprise Attack"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"0c64-f33a-440f-8f3f","profile_id":"478c-e3b9-a7bb-a792"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_assault' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.9297-70b4-8d0b-cacf.46fd-b38d-22b8-9859', 'Contested Outpost', 'Imported from Star_Wars_Armada.gst profile 8.2 Defense Objective.', 'Contested Outpost', '{"characteristics":{"Setup":{"raw_value":"Place obstacles as normal, excluding the station. Then the second player places the station in the setup area beyond distance 1 of all obstacles and beyond distance 5 of both players\u0027 edges.","value":"Place obstacles as normal, excluding the station. Then the second player places the station in the setup area beyond distance 1 of all obstacles and beyond distance 5 of both players\u0027 edges."},"Special Rule":{"raw_value":"The station does not obstruct attacks and does not have the ability to discard damage cards or recover hull points.","value":"The station does not obstruct attacks and does not have the ability to discard damage cards or recover hull points."},"End of Round":{"raw_value":"Each player sums the command values of his ships at distance 1 of the station. The player with the highest total gains 1 victory token.","value":"Each player sums the command values of his ships at distance 1 of the station. The player with the highest total gains 1 victory token."},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"20","value":"20"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.2 Defense Objective","catalogue_entry_name":"Contested Outpost"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"9297-70b4-8d0b-cacf","profile_id":"46fd-b38d-22b8-9859"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.2c91-fa18-6021-bab4.fd2c-e4a6-ffdd-2937', 'Fire Lanes', 'Imported from Star_Wars_Armada.gst profile 8.2 Defense Objective.', 'Fire Lanes', '{"characteristics":{"Setup":{"raw_value":"After placing obstacles, the second player places 3 objective tokens in the setup area beyond distance 4 of both players\u0027 edges. Then the first player may move each objective token to within distance 1-2 of its current location.","value":"After placing obstacles, the second player places 3 objective tokens in the setup area beyond distance 4 of both players\u0027 edges. Then the first player may move each objective token to within distance 1-2 of its current location."},"Special Rule":{"raw_value":"","value":""},"End of Round":{"raw_value":"Each player gains 1 victory token for each objective token he controls. To determine control of each token, players measure attack range and line of sight from each of their ships\u0027 hull zones as if performing attacks with battery armament targeting that objective token. The player with the highest total number of dice in his combined attack pools controls that token. If a player\u0027s ship or squadron overlaps an objective token, his opponent controls that token; if both player\u0027s ships or squadrons overlap the same token, neither player controls it.","value":"Each player gains 1 victory token for each objective token he controls. To determine control of each token, players measure attack range and line of sight from each of their ships\u0027 hull zones as if performing attacks with battery armament targeting that objective token. The player with the highest total number of dice in his combined attack pools controls that token. If a player\u0027s ship or squadron overlaps an objective token, his opponent controls that token; if both player\u0027s ships or squadrons overlap the same token, neither player controls it."},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"15","value":"15"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.2 Defense Objective","catalogue_entry_name":"Fire Lanes"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"2c91-fa18-6021-bab4","profile_id":"fd2c-e4a6-ffdd-2937"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.66da-ed25-4d19-315e.cd5c-fb96-d377-8204', 'Fleet Ambush', 'Imported from Star_Wars_Armada.gst profile 8.2 Defense Objective.', 'Fleet Ambush', '{"characteristics":{"Setup":{"raw_value":"The portion of the setup area that is beyond distance 5 of any edge of the setup area is the Ambush Zone. Players mark the corners of the ambush zone with objective tokens. Players take turns deploying fleets as normal, but must deploy all ships before deploying any squadrons. The first player must deploy ships within the ambush zone on his odd-numbered deployment turns, starting with his first turn. He cannot deploy ships or squadrons overlapping obstacles in the ambush zone. After setup is complete, he removes all objective tokens from the play area.","value":"The portion of the setup area that is beyond distance 5 of any edge of the setup area is the Ambush Zone. Players mark the corners of the ambush zone with objective tokens. Players take turns deploying fleets as normal, but must deploy all ships before deploying any squadrons. The first player must deploy ships within the ambush zone on his odd-numbered deployment turns, starting with his first turn. He cannot deploy ships or squadrons overlapping obstacles in the ambush zone. After setup is complete, he removes all objective tokens from the play area."},"Special Rule":{"raw_value":"","value":""},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"--","value":"--"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.2 Defense Objective","catalogue_entry_name":"Fleet Ambush"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"66da-ed25-4d19-315e","profile_id":"cd5c-fb96-d377-8204"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.7406-dc25-d3a0-abfd.86ab-ce5c-66e8-3321', 'Hyperspace Assault', 'Imported from Star_Wars_Armada.gst profile 8.2 Defense Objective.', 'Hyperspace Assault', '{"characteristics":{"Setup":{"raw_value":"Before deploying fleets, the second player sets aside 1 of his small or medium ships and up to 3 of his squadrons; he does not deploy them during setup. Then he places 3 objective tokens in the play area beyond distance 3 of both players\u0027 starting edges.","value":"Before deploying fleets, the second player sets aside 1 of his small or medium ships and up to 3 of his squadrons; he does not deploy them during setup. Then he places 3 objective tokens in the play area beyond distance 3 of both players\u0027 starting edges."},"Special Rule":{"raw_value":"At the start of any round after the first round, the second player can deploy the ship and squadrons that he set aside at distance 1 of 1 objective token. Then remove all objective tokens. The ship can be deployed overlapping squadrons; the first player places those squadrons as though the ship had overlapped them while executing a maneuver. If the second player does not deploy, he may move each objective token to within distance 1 of its current position.","value":"At the start of any round after the first round, the second player can deploy the ship and squadrons that he set aside at distance 1 of 1 objective token. Then remove all objective tokens. The ship can be deployed overlapping squadrons; the first player places those squadrons as though the ship had overlapped them while executing a maneuver. If the second player does not deploy, he may move each objective token to within distance 1 of its current position."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"--","value":"--"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.2 Defense Objective","catalogue_entry_name":"Hyperspace Assault"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"7406-dc25-d3a0-abfd","profile_id":"86ab-ce5c-66e8-3321"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.074e-26f8-6960-5409.6a67-5bcd-ecc6-dabe', 'Fighter Ambush', 'Imported from Star_Wars_Armada.gst profile 8.2 Defense Objective.', 'Fighter Ambush', '{"characteristics":{"Setup":{"raw_value":"Before deploying fleets, the second player sets aside all of his squadrons. After deploying fleets, the second player deploys all of his squadrons. Each of his squadrons can be placed as normal or at distance 1 of an obstacle, but all his squadrons must be beyond distance 5 of the first player\u0027s edge.","value":"Before deploying fleets, the second player sets aside all of his squadrons. After deploying fleets, the second player deploys all of his squadrons. Each of his squadrons can be placed as normal or at distance 1 of an obstacle, but all his squadrons must be beyond distance 5 of the first player\u0027s edge."},"Special Rule":{"raw_value":"After a squadron performs an attack against a ship, if the defender was dealt at least 1 damage card, the squadron\u0027s owner gains 1 victory token.","value":"After a squadron performs an attack against a ship, if the defender was dealt at least 1 damage card, the squadron\u0027s owner gains 1 victory token."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"15","value":"15"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.2 Defense Objective","catalogue_entry_name":"Fighter Ambush"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"074e-26f8-6960-5409","profile_id":"6a67-5bcd-ecc6-dabe"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.af42-a630-888d-c895.a8e9-9696-170f-2085', 'Jamming Barrier', 'Imported from Star_Wars_Armada.gst profile 8.2 Defense Objective.', 'Jamming Barrier', '{"characteristics":{"Setup":{"raw_value":"Place obstacles as normal, excluding the station and replacing the 2 debris fields with the 2 dust fields. After deploying fleets, the second player places 2 objective tokens in the setup area at distance 1-5 of each other.","value":"Place obstacles as normal, excluding the station and replacing the 2 debris fields with the 2 dust fields. After deploying fleets, the second player places 2 objective tokens in the setup area at distance 1-5 of each other."},"Special Rule":{"raw_value":"While attacking, if line of sight is traced across the line between the two objective tokens, the attacker must choose and remove half of the dice from the attack pool, rounded down, before rolling.","value":"While attacking, if line of sight is traced across the line between the two objective tokens, the attacker must choose and remove half of the dice from the attack pool, rounded down, before rolling."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"--","value":"--"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.2 Defense Objective","catalogue_entry_name":"Jamming Barrier"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"af42-a630-888d-c895","profile_id":"a8e9-9696-170f-2085"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.d4e9-537e-493a-9a16.de5a-97c5-bfef-e47d', 'Planetary Ion Cannon', 'Imported from Star_Wars_Armada.gst profile 8.2 Defense Objective.', 'Planetary Ion Cannon', '{"characteristics":{"Setup":{"raw_value":"After placing obstacles, the second player places 3 objective tokens in the play area beyond distance 5 of both players\u0027 edges.","value":"After placing obstacles, the second player places 3 objective tokens in the play area beyond distance 5 of both players\u0027 edges."},"Special Rule":{"raw_value":"At the end of the Command Phase, the second player may choose 1 enemy ship at distance 1-3 of an objective token and remove that token from the play area to perform an attack against that ship. The attacker is treated as if it is a ship with a battery armament of 4 blue dice, but is not friendly to any ship or squadron. The attack is treated as being at medium range, cannot be obstructed, can target any of the defender\u0027s hull zones, and has the following critical effect: Blue Critical: The defender must choose and exhaust 1 of his defense tokens.","value":"At the end of the Command Phase, the second player may choose 1 enemy ship at distance 1-3 of an objective token and remove that token from the play area to perform an attack against that ship. The attacker is treated as if it is a ship with a battery armament of 4 blue dice, but is not friendly to any ship or squadron. The attack is treated as being at medium range, cannot be obstructed, can target any of the defender\u0027s hull zones, and has the following critical effect: Blue Critical: The defender must choose and exhaust 1 of his defense tokens."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"--","value":"--"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.2 Defense Objective","catalogue_entry_name":"Planetary Ion Cannon"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"d4e9-537e-493a-9a16","profile_id":"de5a-97c5-bfef-e47d"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.a014-3d43-6321-b2bc.4025-9fea-5ac5-b494', 'Capture the VIP', 'Imported from Star_Wars_Armada.gst profile 8.2 Defense Objective.', 'Capture the VIP', '{"characteristics":{"Setup":{"raw_value":"After placing obstacles, the second player places 1 objective token at distance 1 of any obstacle and beyond distance 5 of all edges of the setup area.","value":"After placing obstacles, the second player places 1 objective token at distance 1 of any obstacle and beyond distance 5 of all edges of the setup area."},"Special Rule":{"raw_value":"When a ship at distance 1 of the objective token reveals a command dial, the ship\u0027s owner may remove that objective token from the play area and place it on that ship\u0027s card. When a ship with the objective token on its ship card is destroyed, the opposing player places the objective token in the play area, touching the destroyed ship\u0027s base.","value":"When a ship at distance 1 of the objective token reveals a command dial, the ship\u0027s owner may remove that objective token from the play area and place it on that ship\u0027s card. When a ship with the objective token on its ship card is destroyed, the opposing player places the objective token in the play area, touching the destroyed ship\u0027s base."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"If a player\u0027s ship has the objective token, that player gains 1 victory token.","value":"If a player\u0027s ship has the objective token, that player gains 1 victory token."},"Victory Token Value":{"raw_value":"50","value":"50"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.2 Defense Objective","catalogue_entry_name":"Capture the VIP"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"a014-3d43-6321-b2bc","profile_id":"4025-9fea-5ac5-b494"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.00cb-5ae0-a79c-7608.5a8e-be77-df46-c156', 'Abandoned Mining Facility', 'Imported from Star_Wars_Armada.gst profile 8.2 Defense Objective.', 'Abandoned Mining Facility', '{"characteristics":{"Setup":{"raw_value":"The second player places the station in the center of the setup area. Then starting with the second player, the players alternate placing the remaining obstacles, addin the 2 purrgil and 2 dust fields and excluding the asteriod fields, at distance 2-5 of the station. After deploying fleets, each of the second players\u0027 ships gain a [Engineering] token.","value":"The second player places the station in the center of the setup area. Then starting with the second player, the players alternate placing the remaining obstacles, addin the 2 purrgil and 2 dust fields and excluding the asteriod fields, at distance 2-5 of the station. After deploying fleets, each of the second players\u0027 ships gain a [Engineering] token."},"Special Rule":{"raw_value":"Each ship can resolve the following effect: [Engineering]: You may spend engineering points to gain victory tokens from 1 station or dust field at distance 1. If that obstacle is a station, gain 1 token for each 3 points you spend. If that obstacle is a dust field, gain 1 token for every 2 points you spend. Then, if that obstacle is a dust field and you gained more than 1 victory token, remove that obstacle from the play area.","value":"Each ship can resolve the following effect: [Engineering]: You may spend engineering points to gain victory tokens from 1 station or dust field at distance 1. If that obstacle is a station, gain 1 token for each 3 points you spend. If that obstacle is a dust field, gain 1 token for every 2 points you spend. Then, if that obstacle is a dust field and you gained more than 1 victory token, remove that obstacle from the play area."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"10","value":"10"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.2 Defense Objective","catalogue_entry_name":"Abandoned Mining Facility"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"00cb-5ae0-a79c-7608","profile_id":"5a8e-be77-df46-c156"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.14b6-833f-270d-78d8.3623-7e14-3167-7ead', 'Asteroid Tactics', 'Imported from Star_Wars_Armada.gst profile 8.2 Defense Objective.', 'Asteroid Tactics', '{"characteristics":{"Setup":{"raw_value":"The second player places all obstacles, excluding the station.","value":"The second player places all obstacles, excluding the station."},"Special Rule":{"raw_value":"When one of the first player\u0027s ships or unique squadrons overlaps an astroid field, it may recover 1 of its non-[Scatter] defense tokens. That token must be exhausted. When one of the second player\u0027s ships or unique squadrons overlaps an asteroid field, that obstacle has no effect and that ship or squadron may recover 1 of its non-[Scatter] defense tokens or may ready 1 of its defense tokens. After the start of each squadron phase (after exogorths perform attacks), remove each exogorth obstacle from the play area.","value":"When one of the first player\u0027s ships or unique squadrons overlaps an astroid field, it may recover 1 of its non-[Scatter] defense tokens. That token must be exhausted. When one of the second player\u0027s ships or unique squadrons overlaps an asteroid field, that obstacle has no effect and that ship or squadron may recover 1 of its non-[Scatter] defense tokens or may ready 1 of its defense tokens. After the start of each squadron phase (after exogorths perform attacks), remove each exogorth obstacle from the play area."},"End of Round":{"raw_value":"The second player places the 2 exogorth obstacles, each touching a different obstacle.","value":"The second player places the 2 exogorth obstacles, each touching a different obstacle."},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.2 Defense Objective","catalogue_entry_name":"Asteroid Tactics"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"14b6-833f-270d-78d8","profile_id":"3623-7e14-3167-7ead"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.ac36-0f2d-2385-05f3.8a4d-0913-2030-7c4e', 'Fleet in Being', 'Imported from Star_Wars_Armada.gst profile 8.2 Defense Objective.', 'Fleet in Being', '{"characteristics":{"Setup":{"raw_value":"After deploying fleets, the first player assigns each of their ships 1 objective token. Then the second player assigns each of their ships a number of objective tokens equal to that ships command value.","value":"After deploying fleets, the first player assigns each of their ships 1 objective token. Then the second player assigns each of their ships a number of objective tokens equal to that ships command value."},"Special Rule":{"raw_value":"When a ship with an objective token is declared as the target of an attack, it may discard 1 objective token to ready 1 of its exhausted defense tokens.","value":"When a ship with an objective token is declared as the target of an attack, it may discard 1 objective token to ready 1 of its exhausted defense tokens."},"End of Round":{"raw_value":"If a ship is at distance 1-5 of 1 of the 3\u0027 edges of the play area, or at distance 1-3 of a player edge, remove 1 objective token from that ship.","value":"If a ship is at distance 1-5 of 1 of the 3\u0027 edges of the play area, or at distance 1-3 of a player edge, remove 1 objective token from that ship."},"End of Game":{"raw_value":"Each player gains 1 victory token for each enemy ship in the play area that does not have an objective token.","value":"Each player gains 1 victory token for each enemy ship in the play area that does not have an objective token."},"Victory Token Value":{"raw_value":"15","value":"15"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.2 Defense Objective","catalogue_entry_name":"Fleet in Being"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"ac36-0f2d-2385-05f3","profile_id":"8a4d-0913-2030-7c4e"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.0e82-b0f9-d220-859e.8343-7dc1-099c-44e3', 'Rift Ambush', 'Imported from Star_Wars_Armada.gst profile 8.2 Defense Objective.', 'Rift Ambush', '{"characteristics":{"Setup":{"raw_value":"The second player places all obstacles, adding the gravity rift and 2 dust fields and excluding the station. The gravity rift must be placed beyond distance 5 of both players\u0027 edges. After deploying fleets, the second player may choose 1 enemy ship. That ship must execute a speed-1 maneuver with a yaw of \u0027-\u0027. Then the second player may increase or decrease that ship\u0027s speed by 1, to a minimum speed of 0.","value":"The second player places all obstacles, adding the gravity rift and 2 dust fields and excluding the station. The gravity rift must be placed beyond distance 5 of both players\u0027 edges. After deploying fleets, the second player may choose 1 enemy ship. That ship must execute a speed-1 maneuver with a yaw of \u0027-\u0027. Then the second player may increase or decrease that ship\u0027s speed by 1, to a minimum speed of 0."},"Special Rule":{"raw_value":"Once per activation, after a ship executes a maneuver, if it is at distance 1-2 of the gravity rift, it must execute a speed-1 maneuver with a yaw of \u0027-\u0027. If that ship belongs to the second player, it may use its speed-1 yaw value. The gravity rift does not have the ability to temporarily reduce that ship\u0027s speed during this maneuver.","value":"Once per activation, after a ship executes a maneuver, if it is at distance 1-2 of the gravity rift, it must execute a speed-1 maneuver with a yaw of \u0027-\u0027. If that ship belongs to the second player, it may use its speed-1 yaw value. The gravity rift does not have the ability to temporarily reduce that ship\u0027s speed during this maneuver."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.2 Defense Objective","catalogue_entry_name":"Rift Ambush"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"0e82-b0f9-d220-859e","profile_id":"8343-7dc1-099c-44e3"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.0369-b900-da6a-91a1.bcbd-fabb-208e-0c67', 'Base Defense: Ion Cannon', 'Imported from Star_Wars_Armada.gst profile 8.4 Campaign Objective.', 'Base Defense: Ion Cannon', '{"characteristics":{"Setup":{"raw_value":"The second player must deploy all of his ships and squadron before the first player. After deploying fleets, the second player places 3 objective tokens anywhere in the play area.","value":"The second player must deploy all of his ships and squadron before the first player. After deploying fleets, the second player places 3 objective tokens anywhere in the play area."},"Special Rule":{"raw_value":"At the end of the Command Phase, the second player may select 1 enemy ship at distance 1-3 of an objective token and perform an attack against that ship. The attacker is treated as if it is a ship with a battery armament of 4 blue dice, but is not friendly to any ship or squadrons. The attack is treated as being at medium range, cannot be obstructed, can target any of the defender\u0027s hull zones. and has the following critical effect: Blue [Crit]: The defender must choose and exhaust 1 of his defense tokens.","value":"At the end of the Command Phase, the second player may select 1 enemy ship at distance 1-3 of an objective token and perform an attack against that ship. The attacker is treated as if it is a ship with a battery armament of 4 blue dice, but is not friendly to any ship or squadrons. The attack is treated as being at medium range, cannot be obstructed, can target any of the defender\u0027s hull zones. and has the following critical effect: Blue [Crit]: The defender must choose and exhaust 1 of his defense tokens."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.4 Campaign Objective","catalogue_entry_name":"Base Defense: Ion Cannon"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"0369-b900-da6a-91a1","profile_id":"bcbd-fabb-208e-0c67"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_campaign' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.6b39-c2f9-f8b0-12de.36bb-6e51-e88c-ccb0', 'Hyperlane Raid', 'Imported from Star_Wars_Armada.gst profile 8.4 Campaign Objective.', 'Hyperlane Raid', '{"characteristics":{"Setup":{"raw_value":"After deploying fleets, each player chooses 1 of his ships to be an objective ship, starting with the first player.","value":"After deploying fleets, each player chooses 1 of his ships to be an objective ship, starting with the first player."},"Special Rule":{"raw_value":"The first player\u0027s objective ship may perform each of its attacks from the same hull zone. It cannot target the same hull zone or squadron more than once each round with that hull zone. The second player\u0027s objective ship may perform each of its attacks from the same hull zone, and it may do so against the same targets.","value":"The first player\u0027s objective ship may perform each of its attacks from the same hull zone. It cannot target the same hull zone or squadron more than once each round with that hull zone. The second player\u0027s objective ship may perform each of its attacks from the same hull zone, and it may do so against the same targets."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"The fleet point cost of a destroyed objective ship is doubled. Do not double the cost of its upgrade cards.","value":"The fleet point cost of a destroyed objective ship is doubled. Do not double the cost of its upgrade cards."},"Victory Token Value":{"raw_value":"15","value":"15"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.4 Campaign Objective","catalogue_entry_name":"Hyperlane Raid"}'::jsonb, '{"fi