INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.843b-96ec-2c36-14ac.b962-78ad-e963-4438', 'Base Defense: Armed Station', 'Imported from Star_Wars_Armada.gst profile 8.4 Campaign Objective.', 'Base Defense: Armed Station', '{"characteristics":{"Setup":{"raw_value":"Place obstacles as normal, excluding the station. Then, the second player places the station in the setup area beyond distance 1 of all obstacles and beyond distance 5 of the first player\u0027s edge. The station is an armed station; place the Armed Station card near the second player\u0027s ship cards.","value":"Place obstacles as normal, excluding the station. Then, the second player places the station in the setup area beyond distance 1 of all obstacles and beyond distance 5 of the first player\u0027s edge. The station is an armed station; place the Armed Station card near the second player\u0027s ship cards."},"Special Rule":{"raw_value":"The first player\u0027s ships and squadrons cannot resolve the armed stations effect to discard damage cards or recover hull points when they overlap it. Once per round, instead of activating a ship, the second player can perform 1 attack with the armed station.","value":"The first player\u0027s ships and squadrons cannot resolve the armed stations effect to discard damage cards or recover hull points when they overlap it. Once per round, instead of activating a ship, the second player can perform 1 attack with the armed station."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.4 Campaign Objective","catalogue_entry_name":"Base Defense: Armed Station"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"843b-96ec-2c36-14ac","profile_id":"b962-78ad-e963-4438"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_campaign' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.fbcb-5e25-1102-375a.bfb4-85b6-b537-be54', 'Base Defense: Fighter Wing', 'Imported from Star_Wars_Armada.gst profile 8.4 Campaign Objective.', 'Base Defense: Fighter Wing', '{"characteristics":{"Setup":{"raw_value":"Before deploying fleets, the second player may choose up to 40 fleet points of additional non-unique squadrons and add them to his fleet (even if it exceeds the number of fleet points he could normally spend on squadrons). Assign squadron ID tokens of a different color to these squadrons.","value":"Before deploying fleets, the second player may choose up to 40 fleet points of additional non-unique squadrons and add them to his fleet (even if it exceeds the number of fleet points he could normally spend on squadrons). Assign squadron ID tokens of a different color to these squadrons."},"Special Rule":{"raw_value":"","value":""},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"The fleet point cost of the additional squadrons is added to the first player\u0027s score as normal if they are destroyed. After the winner is determined, the second player removes the additional squadrons from his fleet.","value":"The fleet point cost of the additional squadrons is added to the first player\u0027s score as normal if they are destroyed. After the winner is determined, the second player removes the additional squadrons from his fleet."},"Victory Token Value":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.4 Campaign Objective","catalogue_entry_name":"Base Defense: Fighter Wing"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_