INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.eba9-f909-a315-fb55.b44e-31de-99da-7b62', 'Show Of Force', 'Imported from Star_Wars_Armada.gst profile 8.4 Campaign Objective.', 'Show Of Force', '{"characteristics":{"Setup":{"raw_value":"Place obstacles as normal, excluding the station. Then, the second player places 2 stations in the setup area. Each station must be beyond distance 1 of all obstacles and beyond distance 3 of both players\u0027 edges. Both stations are unarmed stations; place both Unarmed Station cards near the second player\u0027s ship cards.","value":"Place obstacles as normal, excluding the station. Then, the second player places 2 stations in the setup area. Each station must be beyond distance 1 of all obstacles and beyond distance 3 of both players\u0027 edges. Both stations are unarmed stations; place both Unarmed Station cards near the second player\u0027s ship cards."},"Special Rule":{"raw_value":"The first player\u0027s ships and squadrons cannot resolve an unarmed station\u0027s effect to discard damage cards or recover hull points when they overlap it.","value":"The first player\u0027s ships and squadrons cannot resolve an unarmed station\u0027s effect to discard damage cards or recover hull points when they overlap it."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"The second player gains 1 victory token for each unarmed station that is not destroyed. The first player gains 1 victory token and his team gains 40 resource points for each station that is destroyed. The winner\u0027s team also gains 40 resource points if he wins the game.","value":"The second player gains 1 victory token for each unarmed station that is not destroyed. The first player gains 1 victory token and his team gains 40 resource points for each station that is destroyed. The winner\u0027s team also gains 40 resource points if he wins the game."},"Victory Token Value":{"raw_value":"20","value":"20"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.4 Campaign Objective","catalogue_entry_name":"Show Of Force"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"eba9-f909-a315-fb55","profile_id":"b44e-31de-99da-7b62"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_campaign' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.93e7-c426-5231-2e6c.b789-9aa0-280a-7c42', 'Double Agent', 'Imported from Star_Wars_Armada.gst profile 8.4 Campaign Objective.', 'Double Agent', '{"characteristics":{"Setup":{"raw_value":"Place obstacles as normal, excluding the station. After deploying fleets, the second player chooses one of their ships to be objective ship.","value":"Place obstacles as normal, excluding the station. After deploying fleets, the second player chooses one of their ships to be objective ship."},"Special Rule":{"raw_value":"When the objective ship reveals a command dial, it may gain 1 matching command token without spending the command dial. When the objective ship is destroyed, the opposing fleet\u0027s owner gains 1 victory token. Then the opposing player places the objective token in the play area at distance 1 of the destroyed ship. At the start of any round after the second round, if no player has a victory token, the first player may remove the objective token from the objective ship and place the objective token in the play area at distance 1 of that ship. When a ship overlaps the objective token, remove the token from the play area. Then that ship becomes the objective ship and that ship\u0027s owner gains 1 victory token.","value":"When the objective ship reveals a command dial, it may gain 1 matching command token without spending the command dial. When the objective ship is destroyed, the opposing fleet\u0027s owner gains 1 victory token. Then the opposing player places the objective token in the play area at distance 1 of the destroyed ship. At the start of any round after the second round, if no player has a victory token, the first player may remove the objective token from the objective ship and place the objective token in the play area at distance 1 of that ship. When a ship overlaps the objective token, remove the token from the play area. Then that ship becomes the objective ship and that ship\u0027s owner gains 1 victory token."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"20","value":"20"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.4 Campaign Objective","catalogue_entry_name":"Double Agent"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"93e7-c426-5231-2e6c","profile_id":"b789-9aa0-280a-7c42"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_campaign' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.fdb6-cfb0-194b-c26b.6f7a-f9b3-062c-a3c7', 'Hired Scum', 'Imported from Star_Wars_Armada.gst profile 8.4 Campaign Objective.', 'Hired Scum', '{"characteristics":{"Setup":{"raw_value":"The second player places all obstacles, excluding the station. Then the second player chooses 3 obstacles and places 1 objective token on each. Before deploying fleets, the second player chooses up to 40 points of non-unique, irregular squadrons and adds them to their fleet for this game. These squadrons are SCUM and are set aside.","value":"The second player places all obstacles, excluding the station. Then the second player chooses 3 obstacles and places 1 objective token on each. Before deploying fleets, the second player chooses up to 40 points of non-unique, irregular squadrons and adds them to their fleet for this game. These squadrons are SCUM and are set aside."},"Special Rule":{"raw_value":"At the start of any round after the first round, the second player can deploy up to 2 of the scum squadrons at distance 1 of an obstacle with an objective token. Then remove that objective token and 1 other objective token, if able. While a scum squadron is defending, the attacker may reroll 1 die for each friendly ship or squadron at distance 1 of the defender.","value":"At the start of any round after the first round, the second player can deploy up to 2 of the scum squadrons at distance 1 of an obstacle with an objective token. Then remove that objective token and 1 other objective token, if able. While a scum squadron is defending, the attacker may reroll 1 die for each friendly ship or squadron at distance 1 of the defender."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"","value":""},"Victory Token Value":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.4 Campaign Objective","catalogue_entry_name":"Hired Scum"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"fdb6-cfb0-194b-c26b","profile_id":"6f7a-f9b3-062c-a3c7"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_campaign' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.0fca-c9b4-75a5-c68c.4362-deda-674b-9d88', 'HoloNet Override', 'Imported from Star_Wars_Armada.gst profile 8.4 Campaign Objective.', 'HoloNet Override', '{"characteristics":{"Setup":{"raw_value":"The second player places all obstacles. The station must be placed beyond distance 1 of all obstacles and beyond distance 5 of both player\u0027s edges.","value":"The second player places all obstacles. The station must be placed beyond distance 1 of all obstacles and beyond distance 5 of both player\u0027s edges."},"Special Rule":{"raw_value":"The station does not have the ability to discard damage cards or recover hull points. Each ship can resolve the following effect: [Repair]: If you are at distance 1-2 to the station you may spend engineering points to place (or remove) objective tokens on this card. For each 2 points you spend, you may place (or remove) 1 objective token. When one of the second player\u0027s ships resolves this effect, that ship\u0027s owner gains 1 victory token for each objective token it removes.","value":"The station does not have the ability to discard damage cards or recover hull points. Each ship can resolve the following effect: [Repair]: If you are at distance 1-2 to the station you may spend engineering points to place (or remove) objective tokens on this card. For each 2 points you spend, you may place (or remove) 1 objective token. When one of the second player\u0027s ships resolves this effect, that ship\u0027s owner gains 1 victory token for each objective token it removes."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"The first player gains 1 victory token for each objective token on this card.","value":"The first player gains 1 victory token for each objective token on this card."},"Victory Token Value":{"raw_value":"10","value":"10"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.4 Campaign Objective","catalogue_entry_name":"HoloNet Override"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"0fca-c9b4-75a5-c68c","profile_id":"4362-deda-674b-9d88"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_campaign' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.5395-1106-60ee-ea21.f386-5f7f-6c01-f655', 'Pilot Deection', 'Imported from Star_Wars_Armada.gst profile 8.4 Campaign Objective.', 'Pilot Deection', '{"characteristics":{"Setup":{"raw_value":"Before deploying fleets, the first player must choose 3 additional non-unique squadrons of the opposing faction with a total value up to 40 points and add them to the second players fleet for this battle.","value":"Before deploying fleets, the first player must choose 3 additional non-unique squadrons of the opposing faction with a total value up to 40 points and add them to the second players fleet for this battle."},"Special Rule":{"raw_value":"Once per game, at the start of any Squadron Phase, the first player may assign 1 objective token to 1 of the chosen squadrons. This squadron is the defector and is added to the first player\u0027s fleet for the remainder of the game. When the defector is destroyed, the second player gains 1 victory token.","value":"Once per game, at the start of any Squadron Phase, the first player may assign 1 objective token to 1 of the chosen squadrons. This squadron is the defector and is added to the first player\u0027s fleet for the remainder of the game. When the defector is destroyed, the second player gains 1 victory token."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"If the defector is at distance 1 of one of the first player\u0027s ships and beyond distance 1 of enemy ships or squadrons, the first player gains 1 victory token.","value":"If the defector is at distance 1 of one of the first player\u0027s ships and beyond distance 1 of enemy ships or squadrons, the first player gains 1 victory token."},"Victory Token Value":{"raw_value":"25","value":"25"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.4 Campaign Objective","catalogue_entry_name":"Pilot Deection"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"5395-1106-60ee-ea21","profile_id":"f386-5f7f-6c01-f655"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_campaign' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.5975-9cd1-6982-c807.7eb5-3d2a-faeb-a53e', 'Prototype Recovery', 'Imported from Star_Wars_Armada.gst profile 8.4 Campaign Objective.', 'Prototype Recovery', '{"characteristics":{"Setup":{"raw_value":"Before deploying fleets, the second player must choose 1 additional non-unique squadron with a total value of 8-20 points*. This is the prototype, and is set aside. After placing obstacles, the first player places an objective token in the center of the play area.","value":"Before deploying fleets, the second player must choose 1 additional non-unique squadron with a total value of 8-20 points*. This is the prototype, and is set aside. After placing obstacles, the first player places an objective token in the center of the play area."},"Special Rule":{"raw_value":"When a ship at distance 1 of an objective token resolves a [Squadron] command, instead of activating squardons, that ship\u0027s owner may roll 1 blue die. If a [Crit] icon is rolled, the prototype is added to the player\u0027s fleet for the remainder of the game. If that ship belongs to the second player, the prototype is added if a [Hit] icon is rolled instead. Then the controlling player deploys the prototype at distance 1 of the objective token and discards the token. While the prototype is attacking, each [Crit] icon adds 1 to the damage total.","value":"When a ship at distance 1 of an objective token resolves a [Squadron] command, instead of activating squardons, that ship\u0027s owner may roll 1 blue die. If a [Crit] icon is rolled, the prototype is added to the player\u0027s fleet for the remainder of the game. If that ship belongs to the second player, the prototype is added if a [Hit] icon is rolled instead. Then the controlling player deploys the prototype at distance 1 of the objective token and discards the token. While the prototype is attacking, each [Crit] icon adds 1 to the damage total."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"If the prototype is in the play area, the controlling player gains 1 victory token.","value":"If the prototype is in the play area, the controlling player gains 1 victory token."},"Victory Token Value":{"raw_value":"30","value":"30"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.4 Campaign Objective","catalogue_entry_name":"Prototype Recovery"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"5975-9cd1-6982-c807","profile_id":"7eb5-3d2a-faeb-a53e"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_campaign' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.581f-8284-ea33-9552.b02b-1ac7-c744-6bd9', 'Recruit Allies', 'Imported from Star_Wars_Armada.gst profile 8.4 Campaign Objective.', 'Recruit Allies', '{"characteristics":{"Setup":{"raw_value":"Place obstacles as normal, excluding the station. Before deploying fleets, the first player must choose 30-50 fleet points of non-unique, irregular squadrons or ships with no upgrades equipped. These forces are allies and are set aside. Then the second player places 1 objective token in the play area beyond distance 5 of both players\u0027 edges.","value":"Place obstacles as normal, excluding the station. Before deploying fleets, the first player must choose 30-50 fleet points of non-unique, irregular squadrons or ships with no upgrades equipped. These forces are allies and are set aside. Then the second player places 1 objective token in the play area beyond distance 5 of both players\u0027 edges."},"Special Rule":{"raw_value":"At the end of the third round, each player sums the command value of their ships at distance 1 of the objective token. The player with the highest total adds the allies to their fleet for the remainder of the game. Then that player deploys the allies at distance 1 of the objective token. If the command value totals are equal, the second player adds the allies to their fleet.","value":"At the end of the third round, each player sums the command value of their ships at distance 1 of the objective token. The player with the highest total adds the allies to their fleet for the remainder of the game. Then that player deploys the allies at distance 1 of the objective token. If the command value totals are equal, the second player adds the allies to their fleet."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"The player controlling the allies adds the fleet value of allies remaining in the play area to their score.","value":"The player controlling the allies adds the fleet value of allies remaining in the play area to their score."},"Victory Token Value":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.4 Campaign Objective","catalogue_entry_name":"Recruit Allies"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"581f-8284-ea33-9552","profile_id":"b02b-1ac7-c744-6bd9"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_campaign' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.7a08-fb5b-aab9-2ca6.6524-8189-146f-9812', 'Steal Suppies', 'Imported from Star_Wars_Armada.gst profile 8.4 Campaign Objective.', 'Steal Suppies', '{"characteristics":{"Setup":{"raw_value":"The second player places all obstables, excluding the station. Then the second player places the station beyond distance 5 of both players edges and beyond distance 1 of other obstacles. Then the second player places 6 objective tokens on this card.","value":"The second player places all obstables, excluding the station. Then the second player places the station beyond distance 5 of both players edges and beyond distance 1 of other obstacles. Then the second player places 6 objective tokens on this card."},"Special Rule":{"raw_value":"When one of the first player\u0027s ships at distance 1 of the station reveals its command dial, it may remove 1 objective token from this card and place it on that ship\u0027s card or a friendly irregular squadron at distance 1 of that ship. A ship cannot have more objective tokens than its command value. A squadron can only have 1 objective token on it. When a ship or squadron with at least 1 objective token is destroyed the second player gains 1 victory token.","value":"When one of the first player\u0027s ships at distance 1 of the station reveals its command dial, it may remove 1 objective token from this card and place it on that ship\u0027s card or a friendly irregular squadron at distance 1 of that ship. A ship cannot have more objective tokens than its command value. A squadron can only have 1 objective token on it. When a ship or squadron with at least 1 objective token is destroyed the second player gains 1 victory token."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"The first player gains 1 victory token for each objective token on their ships or squadrons that are beyond distance 2 of enemy ships. The second player gains 1 victory token for each objective token on this card.","value":"The first player gains 1 victory token for each objective token on their ships or squadrons that are beyond distance 2 of enemy ships. The second player gains 1 victory token for each objective token on this card."},"Victory Token Value":{"raw_value":"15","value":"15"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.4 Campaign Objective","catalogue_entry_name":"Steal Suppies"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"7a08-fb5b-aab9-2ca6","profile_id":"6524-8189-146f-9812"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_campaign' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.fc81-9ce8-9473-e15a.185c-f89f-145b-74f6', 'Volatile Cargo', 'Imported from Star_Wars_Armada.gst profile 8.4 Campaign Objective.', 'Volatile Cargo', '{"characteristics":{"Setup":{"raw_value":"Place obstacles as normal, excluding the station.","value":"Place obstacles as normal, excluding the station."},"Special Rule":{"raw_value":"The second player chooses 3 of their ships or squadrons (at least 1 must be a ship) to be objective ships or squadrons and assigns an objective token to each. The first player gains 1 victory token for each objecive token that cannot be assigned. While an objective ship or squadron is defending, before it suffers damage, it may reduce the total damage by 1. If the defender is destroyed during that attack, each other ship and squadron at distance 1-2 of the defender suffers damage equal to half of the total number of [Hit] icons in the attack pool, rounded up. Then the first player gains 1 victory token.","value":"The second player chooses 3 of their ships or squadrons (at least 1 must be a ship) to be objective ships or squadrons and assigns an objective token to each. The first player gains 1 victory token for each objecive token that cannot be assigned. While an objective ship or squadron is defending, before it suffers damage, it may reduce the total damage by 1. If the defender is destroyed during that attack, each other ship and squadron at distance 1-2 of the defender suffers damage equal to half of the total number of [Hit] icons in the attack pool, rounded up. Then the first player gains 1 victory token."},"End of Round":{"raw_value":"","value":""},"End of Game":{"raw_value":"The second player gains 2 victory tokens for each objective ship or squadron at distance 1-3 of the first player\u0027s edge.","value":"The second player gains 2 victory tokens for each objective ship or squadron at distance 1-3 of the first player\u0027s edge."},"Victory Token Value":{"raw_value":"15","value":"15"}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.4 Campaign Objective","catalogue_entry_name":"Volatile Cargo"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"fc81-9ce8-9473-e15a","profile_id":"185c-f89f-145b-74f6"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_campaign' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, display_text, object_data_json, source_reference_json) SELECT g.game_id, got.game_object_type_id, 'armada.star_wars_armada.1b8a-cfe6-a587-9139.b1f0-d5c8-8b0e-9092', 'Summa of all Things', 'Imported from Star_Wars_Armada.gst profile 8.5 Scenario Objective.', 'Summa of all Things', '{"characteristics":{"Setup":{"raw_value":"This scenario is played on a 3\u0027 x 3\u0027 play area. The setup area is the entire play area. Players will set up on opposite sides of this play area. Before placing obstacles, the second player places the Summa-verminoth obstacle in the center of the setup area. Then place objectives as normal, excluding the station, in the setup area. Obstacles must be placed beyond distance 3 of the edges of the play area and beyond distance 1 of each other. After placing the obstacles, the players alternate placing a total of five coaxium canister objective tokens in the setup area, starting with the second player. The first four coaxium canisters must be placed within distance 1 of the Summa-verminoth and not within distance 1 of any other coaxium canister. The fifth coaxium canister must be placed touching the Summa-verminoth and not overlapping any other coaxium canister. Squadrons must be placed within distance 1 of a friendly ship. They may be placed outside deployment zones but not outside the setup area.","value":"This scenario is played on a 3\u0027 x 3\u0027 play area. The setup area is the entire play area. Players will set up on opposite sides of this play area. Before placing obstacles, the second player places the Summa-verminoth obstacle in the center of the setup area. Then place objectives as normal, excluding the station, in the setup area. Obstacles must be placed beyond distance 3 of the edges of the play area and beyond distance 1 of each other. After placing the obstacles, the players alternate placing a total of five coaxium canister objective tokens in the setup area, starting with the second player. The first four coaxium canisters must be placed within distance 1 of the Summa-verminoth and not within distance 1 of any other coaxium canister. The fifth coaxium canister must be placed touching the Summa-verminoth and not overlapping any other coaxium canister. Squadrons must be placed within distance 1 of a friendly ship. They may be placed outside deployment zones but not outside the setup area."},"Special Rule":{"raw_value":"Making up lost time: At the start of the first round, each of the second player\u0027s ships gain a [navigate] token. Volatile Coaxium: Coaxium canisters cannot be moved by [strategic]. Coaxium Recovery: When a ship or unique squadron activates, its controlling player may chose one coaxium canister at distance 1 of that ship or unique squadron to recover. Remove the chosen coaxium canister from the play area and place it on the activating ship or unique squadron\u0027s card. When a ship or unique squadron that has any recovered coaxium canisters is destroyed, the opposing player places them in the play area touching that model\u0027s base before the model is removed. A ship or unique squadron can have multiple coaxium canisters on its card. The Maelstrom: Starting on the second round, at the start of each round and before any player resolves any effects, the second player rolls a blue die and consults the Maelstrom effects chart. Maelstrom effects last until the end of the round.","value":"Making up lost time: At the start of the first round, each of the second player\u0027s ships gain a [navigate] token. Volatile Coaxium: Coaxium canisters cannot be moved by [strategic]. Coaxium Recovery: When a ship or unique squadron activates, its controlling player may chose one coaxium canister at distance 1 of that ship or unique squadron to recover. Remove the chosen coaxium canister from the play area and place it on the activating ship or unique squadron\u0027s card. When a ship or unique squadron that has any recovered coaxium canisters is destroyed, the opposing player places them in the play area touching that model\u0027s base before the model is removed. A ship or unique squadron can have multiple coaxium canisters on its card. The Maelstrom: Starting on the second round, at the start of each round and before any player resolves any effects, the second player rolls a blue die and consults the Maelstrom effects chart. Maelstrom effects last until the end of the round."},"End of Round":{"raw_value":"Remove the Summa-verminoth control token from the play area. If the Summa-verminoth is within a player\u0027s deployment zone, the game ends in a loss for that player.","value":"Remove the Summa-verminoth control token from the play area. If the Summa-verminoth is within a player\u0027s deployment zone, the game ends in a loss for that player."},"End of Game":{"raw_value":"At the end of the game check to see if either player has any ships in the play area. If a player has no ships in the play area, they lose. If both players still have ships in the play area, the player who has the most coaxium canisters on friendly ship and unique squadron cards wins. If neither player has more coaxium canisters on freindly ship and unique squadron cards, the game ends in a draw.","value":"At the end of the game check to see if either player has any ships in the play area. If a player has no ships in the play area, they lose. If both players still have ships in the play area, the player who has the most coaxium canisters on friendly ship and unique squadron cards wins. If neither player has more coaxium canisters on freindly ship and unique squadron cards, the game ends in a draw."},"Victory Token Value":{"raw_value":"","value":""}},"costs":[{"name":"pts","value":"0.0"}],"constraints":[{"field":"selections","scope":"parent","value":"1.0","type":"max"},{"field":"selections","scope":"roster","value":"1.0","type":"max"}],"profile_type":"8.5 Scenario Objective","catalogue_entry_name":"Summa of all Things"}'::jsonb, '{"file":"Star_Wars_Armada.gst","revision":"41","entry_id":"1b8a-cfe6-a587-9139","profile_id":"b1f0-d5c8-8b0e-9092"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'card.objective_scenario' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'objective_deck', 'Objective Deck', '{"deck_type":"objective","status":"reference_only"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'deck.objective' WHERE g.game_name = 'Star Wars: Armada';
