INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'token_evade', 'Evade', '{"token_type":"Evade"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'token.defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'token_contain', 'Contain', '{"token_type":"Contain"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'token.defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'token_salvo', 'Salvo', '{"token_type":"Salvo"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'token.defense' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'token_concentrate_fire', 'Concentrate Fire', '{"token_type":"Concentrate Fire"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'token.command' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'token_navigate', 'Navigate', '{"token_type":"Navigate"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'token.command' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'token_repair', 'Repair', '{"token_type":"Repair"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'token.command' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'token_squadron', 'Squadron', '{"token_type":"Squadron"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'token.command' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'die_red', 'Red attack die', '{"color":"Red"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'die.attack' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'die_blue', 'Blue attack die', '{"color":"Blue"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'die.attack' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'die_black', 'Black attack die', '{"color":"Black"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'die.attack' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'command_dial', 'Command dial', '{"dial_type":"command"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'dial.command' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'speed_dial', 'Speed dial', '{"dial_type":"speed"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'dial.speed' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'ship_base', 'Ship base', '{"geometry":"ship_base","status":"reference_only"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'base.ship' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT g.game_id, got.game_object_type_id, 'squadron_base', 'Squadron base', '{"geometry":"squadron_base","status":"reference_only"}'::jsonb FROM game g JOIN game_object_type got ON got.game_id = g.game_id AND got.object_type_code = 'base.squadron' WHERE g.game_name = 'Star Wars: Armada';
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_description, object_data_json) SELECT f.game_id, got.game_object_type_id, 'unit_variant:' || uv.unit_variant_id, uv.unit_variant_name, uv.unit_variant_description, jsonb_build_object('unit_variant_id', uv.unit_variant_id, 'unit_type_id', ut.unit_type_id, 'classification', uc.unit_classification_name, 'faction', f.faction_name) FROM unit_variant uv JOIN unit_type ut ON ut.unit_type_id = uv.unit_type_id JOIN unit_classification uc ON uc.unit_classification_id = ut.unit_classification_id JOIN faction f ON f.faction_id = uc.faction_id JOIN game_object_type got ON got.game_id = f.game_id AND got.object_type_code = 'card.unit' WHERE f.game_id = (SELECT game_id FROM game WHERE game_name = 'Star Wars: Armada');
INSERT INTO unit_variant_game_object (unit_variant_id, game_object_id, usage_code) SELECT uv.unit_variant_id, go.game_object_id, 'unit_card' FROM unit_variant uv JOIN game_object go ON go.object_code = 'unit_variant:' || uv.unit_variant_id;
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT f.game_id, got.game_object_type_id, 'attack_profile:' || uvc.unit_variant_characteristic_id, uv.unit_variant_name || ' ' || ct.characteristic_type_name, uvc.characteristic_json FROM unit_variant_characteristic uvc JOIN unit_variant uv ON uv.unit_variant_id = uvc.unit_variant_id JOIN unit_type ut ON ut.unit_type_id = uv.unit_type_id JOIN unit_classification uc ON uc.unit_classification_id = ut.unit_classification_id JOIN faction f ON f.faction_id = uc.faction_id JOIN characteristic_type ct ON ct.characteristic_type_id = uvc.characteristic_type_id JOIN game_object_type got ON got.game_id = f.game_id AND got.object_type_code = 'profile.attack' WHERE ct.characteristic_type_name = 'Anti-Squadron' OR ct.characteristic_type_name LIKE '%Firing Arc';
INSERT INTO unit_variant_game_object (unit_variant_id, game_object_id, usage_code) SELECT uvc.unit_variant_id, go.game_object_id, 'attack_profile' FROM unit_variant_characteristic uvc JOIN game_object go ON go.object_code = 'attack_profile:' || uvc.unit_variant_characteristic_id;
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT f.game_id, got.game_object_type_id, 'movement_profile:' || uv.unit_variant_id, uv.unit_variant_name || ' movement', jsonb_object_agg(ct.characteristic_type_name, uvc.characteristic_json) FROM unit_variant uv JOIN unit_type ut ON ut.unit_type_id = uv.unit_type_id JOIN unit_classification uc ON uc.unit_classification_id = ut.unit_classification_id JOIN faction f ON f.faction_id = uc.faction_id JOIN unit_variant_characteristic uvc ON uvc.unit_variant_id = uv.unit_variant_id JOIN characteristic_type ct ON ct.characteristic_type_id = uvc.characteristic_type_id JOIN game_object_type got ON got.game_id = f.game_id AND got.object_type_code = 'profile.movement' WHERE ct.characteristic_type_name IN ('Speed', 'Max Speed') GROUP BY f.game_id, got.game_object_type_id, uv.unit_variant_id, uv.unit_variant_name;
INSERT INTO unit_variant_game_object (unit_variant_id, game_object_id, usage_code) SELECT uv.unit_variant_id, go.game_object_id, 'movement_profile' FROM unit_variant uv JOIN game_object go ON go.object_code = 'movement_profile:' || uv.unit_variant_id;
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT f.game_id, got.game_object_type_id, 'ability:' || uvc.unit_variant_characteristic_id, uv.unit_variant_name || ' ability', uvc.characteristic_json FROM unit_variant_characteristic uvc JOIN unit_variant uv ON uv.unit_variant_id = uvc.unit_variant_id JOIN unit_type ut ON ut.unit_type_id = uv.unit_type_id JOIN unit_classification uc ON uc.unit_classification_id = ut.unit_classification_id JOIN faction f ON f.faction_id = uc.faction_id JOIN characteristic_type ct ON ct.characteristic_type_id = uvc.characteristic_type_id JOIN game_object_type got ON got.game_id = f.game_id AND got.object_type_code = 'ability' WHERE ct.characteristic_type_name = 'Squadron Ability';
INSERT INTO unit_variant_game_object (unit_variant_id, game_object_id, usage_code) SELECT uvc.unit_variant_id, go.game_object_id, 'ability' FROM unit_variant_characteristic uvc JOIN characteristic_type ct ON ct.characteristic_type_id = uvc.characteristic_type_id JOIN game_object go ON go.object_code = 'ability:' || uvc.unit_variant_characteristic_id WHERE ct.characteristic_type_name = 'Squadron Ability';
INSERT INTO unit_variant_game_object (unit_variant_id, game_object_id, usage_code, quantity) SELECT uvc.unit_variant_id, go.game_object_id, 'defense_token', (token->>'count')::integer FROM unit_variant_characteristic uvc CROSS JOIN LATERAL jsonb_array_elements(uvc.characteristic_json->'value') token JOIN characteristic_type ct ON ct.characteristic_type_id = uvc.characteristic_type_id JOIN game_object go ON go.object_name = token->>'name' AND go.object_code LIKE 'token_%' WHERE ct.characteristic_type_name = 'Defense Tokens' AND (token->>'count')::integer > 0 ON CONFLICT DO NOTHING;
INSERT INTO game_object (game_id, game_object_type_id, object_code, object_name, object_data_json) SELECT DISTINCT f.game_id, got.game_object_type_id, 'keyword:' || md5(keyword.value), keyword.value, jsonb_build_object('keyword', keyword.value) FROM unit_variant_characteristic uvc JOIN unit_variant uv ON uv.unit_variant_id = uvc.unit_variant_id JOIN unit_type ut ON ut.unit_type_id = uv.unit_type_id JOIN unit_classification uc ON uc.unit_classification_id = ut.unit_classification_id JOIN faction f ON f.faction_id = uc.faction_id JOIN characteristic_type ct ON ct.characteristic_type_id = uvc.characteristic_type_id CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(uvc.characteristic_json->'value'->'keywords') = 'array' THEN uvc.characteristic_json->'value'->'keywords' ELSE '[]'::jsonb END) keyword JOIN game_object_type got ON got.game_id = f.game_id AND got.object_type_code = 'keyword';
INSERT INTO unit_variant_game_object (unit_variant_id, game_object_id, usage_code) SELECT DISTINCT uvc.unit_variant_id, go.game_object_id, 'keyword' FROM unit_variant_characteristic uvc JOIN unit_variant uv ON uv.unit_variant_id = uvc.unit_variant_id JOIN unit_type ut ON ut.unit_type_id = uv.unit_type_id JOIN unit_classification uc ON uc.unit_classification_id = ut.unit_classification_id JOIN faction f ON f.faction_id = uc.faction_id JOIN characteristic_type ct ON ct.characteristic_type_id = uvc.characteristic_type_id CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(uvc.characteristic_json->'value'->'keywords') = 'array' THEN uvc.characteristic_json->'value'->'keywords' ELSE '[]'::jsonb END) keyword JOIN game_object go ON go.object_code = 'keyword:' || md5(keyword.value) WHERE ct.characteristic_type_name = 'Keywords';
INSERT INTO scenario_definition (game_id, scenario_code, scenario_name, scenario_description, scenario_config_json) SELECT game_id, 'standard_battle', 'Standard Battle Scenario', 'Reference scenario container for the three standard objective categories.', '{"objective_categories": ["assault","defense","navigation"],"status":"reference_only"}'::jsonb FROM game WHERE game_name = 'Star Wars: Armada';
INSERT INTO board_definition (game_id, board_code, board_name, width, height, coordinate_system, board_config_json) SELECT game_id, 'standard_6x3', 'Standard 6 ft x 3 ft play area', 1800, 900, 'continuous_2d_mm', '{"source":"standard Armada play area","status":"reference_only"}'::jsonb FROM game WHERE game_name = 'Star Wars: Armada';
INSERT INTO scenario_board (scenario_id, board_definition_id) SELECT s.scenario_id, b.board_definition_id FROM scenario_definition s JOIN board_definition b ON b.game_id = s.game_id WHERE s.scenario_code = 'standard_battle' AND b.board_code = 'standard_6x3';
INSERT INTO game_mode_scenario (game_mode_id, scenario_id, is_default) SELECT gm.game_mode_id, s.scenario_id, true FROM game_mode gm JOIN scenario_definition s ON s.game_id = gm.game_id WHERE gm.game_mode_code = 'standard_battle' AND s.scenario_code = 'standard_battle';
INSERT INTO game_mode_scenario (game_mode_id, scenario_id, is_default) SELECT gm.game_mode_id, s.scenario_id, false FROM game_mode gm JOIN scenario_definition s ON s.game_id = gm.game_id WHERE gm.game_mode_code = 'fleet_battle' AND s.scenario_code = 'standard_battle';
INSERT INTO scenario_game_object (scenario_id, game_object_id, usage_code) SELECT s.scenario_id, go.game_object_id, 'objective_card' FROM scenario_definition s JOIN game_object go ON go.game_id = (SELECT game_id FROM game WHERE game_name = 'Star Wars: Armada') JOIN game_object_type got ON got.game_object_type_id = go.game_object_type_id WHERE s.scenario_code = 'standard_battle' AND got.object_type_code IN ('card.objective_assault', 'card.objective_defense', 'card.objective_navigation');
INSERT INTO game_mode_game_object (game_mode_id, game_object_id, usage_code) SELECT gm.game_mode_id, go.game_object_id, 'objective_card' FROM game_mode gm JOIN game_object go ON go.game_id = gm.game_id JOIN game_object_type got ON got.game_object_type_id = go.game_object_type_id WHERE got.object_type_code IN ('card.objective_assault', 'card.objective_defense', 'card.objective_navigation');
INSERT INTO fleet_format (game_mode_id, format_code, format_name, points_limit, format_config_json) SELECT game_mode_id, 'standard_fleet', 'Standard fleet', 400, '{"ship_limit":3,"squadron_limit":5,"status":"reference_only"}'::jsonb FROM game_mode WHERE game_mode_code = 'standard_battle';
INSERT INTO fleet_format (game_mode_id, format_code, format_name, points_limit, format_config_json) SELECT game_mode_id, 'standard_fleet', 'Standard fleet', 400, '{"ship_limit":3,"squadron_limit":5,"status":"reference_only"}'::jsonb FROM game_mode WHERE game_mode_code = 'fleet_battle';
INSERT INTO fleet_format_faction (fleet_format_id, faction_id) SELECT ff.fleet_format_id, f.faction_id FROM fleet_format ff JOIN game_mode gm ON gm.game_mode_id = ff.game_mode_id JOIN faction f ON f.game_id = gm.game_id;
INSERT INTO fleet_unit_limit (fleet_format_id, unit_classification_id, maximum_count, limit_config_json) SELECT ff.fleet_format_id, uc.unit_classification_id, CASE uc.unit_classification_name WHEN 'Ship' THEN 3 WHEN 'Squadron' THEN 5 END, '{"source":"standard fleet reference","status":"reference_only"}'::jsonb FROM fleet_format ff JOIN game_mode gm ON gm.game_mode_id = ff.game_mode_id JOIN faction f ON f.game_id = gm.game_id JOIN unit_classification uc ON uc.faction_id = f.faction_id GROUP BY ff.fleet_format_id, uc.unit_classification_id, uc.unit_classification_name;
